def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        return 'C' if history[1][1] == 'C' else 'D'

    opp_recent = [history[i][1] for i in range(max(0, n - 10), n)]
    my_recent = [history[i][0] for i in range(max(0, n - 10), n)]

    opp_last = history[n - 1][1]
    my_last = history[n - 1][0]

    opp_c = opp_recent.count('C')
    opp_d = len(opp_recent) - opp_c

    total_opp_c = sum(1 for a, b in history if b == 'C')
    total_opp_d = n - total_opp_c
    total_my_c = sum(1 for a, b in history if a == 'C')
    total_my_d = n - total_my_c

    # Detect always defect
    if n >= 5 and total_opp_d == n:
        return 'D'

    # Detect always cooperate
    if n >= 5 and total_opp_c == n:
        return 'C'

    # Detect mostly alternating / noisy tit-for-tat-like patterns
    if n >= 6:
        same_recent = sum(1 for i in range(n - 5, n) if history[i][0] == history[i][1])
        if same_recent >= 5:
            return 'C' if opp_last == 'C' else 'D'

    # If opponent has defected on my last cooperation, be cautious
    if my_last == 'C' and opp_last == 'D':
        if opp_d >= opp_c + 2:
            return 'D'
        # retaliate once but forgive
        if n >= 2 and history[n - 2][1] == 'D':
            return 'C'
        return 'D'

    # If opponent has been cooperating and I defected, try to restore cooperation
    if my_last == 'D' and opp_last == 'C':
        if opp_c >= 3:
            return 'C'
        return 'D'

    # Endgame: last few rounds, defect if profitable
    remaining = 100 - n
    if remaining <= 3:
        if opp_c > opp_d:
            return 'D'
        return 'D'

    # Default: cooperate if opponent mostly cooperates
    if opp_c >= opp_d:
        return 'C'
    else:
        # occasional forgiveness
        if rng.random() < 0.1:
            return 'C'
        return 'D'

